		&--might-standard {
			//aspect-ratio: 1188 / 697;
			min-height: 9.41rem;

			.brumes-story-theme--category {
				display: none;
			}
		}

		&--category {
			font-family: "IM Fell Great Primer", serif;
			font-variant: small-caps;
			font-weight: bold;
			font-size: 0.75em;
			text-align: center;
			margin-bottom: 0.2em;
		}

		&--title-box {
			font-size: 2em;
			font-family: "IM Fell English", serif;
			font-style: italic;
			width: 100%;
			text-align: center;
			line-height: 1em;
			margin-bottom: 0.3em;
		}

		&--title {
			//background: var(--brumes-power-color);
			background: linear-gradient(var(--brumes-power-color) 0 0) 0/100%
				15px no-repeat;
			box-decoration-break: clone;
			border: none;
		}

		&--tags {
			list-style: none;
			padding: 0;
			margin: 0;
			display: flex;
			flex-direction: column;
			align-items: center;
			gap: 0.25em;
			text-align: center;

			& > li {
				margin-inline-start: 0 !important;
				line-height: 0;
				padding: 0;
			}
		}
	}

	.brumes-story-theme {
		background-image: url(data:image/png;base64,);
	}

	.brumes-story-theme--might-origin {
		background-image: url(data:image/png;base64,);
	}

	.brumes-story-theme--might-adventure {
		background-image: url(data:image/png;base64,);
	}

	.brumes-story-theme--might-greatness {
		background-image: url(data:image/png;base64,);
	}
}
